@section('content')<section class="tr-page"><div class="tr-shell"><div class="tr-page-head"><div><span class="tr-eyebrow">Product discovery</span><h1>Compare products</h1><p>Compare up to four products side-by-side.</p></div>@if($products->isNotEmpty())<form method="POST" action="{{ route('compare.clear') }}">@csrf @method('DELETE')<button class="btn btn-outline-light">Clear compare</button></form>@endif</div>@if($products->isEmpty())<div class="tr-empty tr-card"><i class="fa-solid fa-scale-balanced"></i><h4>Your compare list is empty</h4><p>Add products from the shop and they will appear here.</p><a class="btn btn-primary" href="{{ route('products.index') }}">Browse products</a></div>@else<div class="tr-compare-wrap"><div class="table-responsive"><table class="tr-compare-table"><tbody><tr><th>Product</th>@foreach($products as $product)<td><div class="tr-compare-product"><img src="{{ $product->thumbnail_url }}" alt="{{ $product->name }}"><h5>{{ $product->name }}</h5><small>{{ $product->category?->name }}</small><a class="btn btn-sm btn-primary mt-3" href="{{ route('products.show',$product->slug) }}">View product</a><form method="POST" action="{{ route('compare.remove',$product) }}">@csrf @method('DELETE')<button class="btn btn-sm btn-link text-danger">Remove</button></form></div></td>@endforeach</tr><tr><th>Price</th>@foreach($products as $product)<td><strong class="fs-5">{{ App\Models\Setting::get('currency_symbol','Rs') }} {{ number_format($product->price,2) }}</strong></td>@endforeach</tr><tr><th>SKU</th>@foreach($products as $product)<td>{{ $product->sku ?: '—' }}</td>@endforeach</tr><tr><th>Availability</th>@foreach($products as $product)<td><span class="tr-status {{ $product->stock_quantity > 0 ? 'approved' : 'rejected' }}">{{ $product->stock_quantity > 0 ? 'In stock' : 'Out of stock' }}</span></td>@endforeach</tr><tr><th>Rating</th>@foreach($products as $product)<td><span class="tr-stars">★ {{ number_format($product->average_rating,1) }}</span><small class="d-block text-muted">{{ $product->total_reviews }} reviews</small></td>@endforeach</tr><tr><th>Variants</th>@foreach($products as $product)<td>{{ $product->variations->where('status',true)->count() ?: 'Standard' }}</td>@endforeach</tr><tr><th>Description</th>@foreach($products as $product)<td><p class="text-muted small mb-0">{{ Str::limit(strip_tags($product->description),180) }}</p></td>@endforeach</tr></tbody></table></div></div>@endif</div></section>@endsection
